-- 回滚：仅删掉本迁移登记的 6 个路径（center 的 GET/PUT 同路径，按 v1 一起删）。
DELETE FROM sys_menu_api WHERE api_id IN (SELECT id FROM sys_api WHERE BINARY path IN (BINARY '/api/gb28181/device-mgmt/map/markers',BINARY '/api/gb28181/device-mgmt/map/clusters',BINARY '/api/gb28181/device-mgmt/map/no-coord-count',BINARY '/api/gb28181/device-mgmt/map/channel-tree',BINARY '/api/gb28181/device-mgmt/map/trajectory',BINARY '/api/gb28181/device-mgmt/map/center'));
DELETE FROM sys_casbin_rule WHERE BINARY v1 IN (BINARY '/api/gb28181/device-mgmt/map/markers',BINARY '/api/gb28181/device-mgmt/map/clusters',BINARY '/api/gb28181/device-mgmt/map/no-coord-count',BINARY '/api/gb28181/device-mgmt/map/channel-tree',BINARY '/api/gb28181/device-mgmt/map/trajectory',BINARY '/api/gb28181/device-mgmt/map/center');
DELETE FROM sys_api WHERE BINARY path IN (BINARY '/api/gb28181/device-mgmt/map/markers',BINARY '/api/gb28181/device-mgmt/map/clusters',BINARY '/api/gb28181/device-mgmt/map/no-coord-count',BINARY '/api/gb28181/device-mgmt/map/channel-tree',BINARY '/api/gb28181/device-mgmt/map/trajectory',BINARY '/api/gb28181/device-mgmt/map/center');
